/* Start custom CSS for container, class: .elementor-element-2a67a07 *//* =========================================
   CARD GRID + CONNECTING LINES
   Section ID: card-box
========================================= */
#card-box{position:relative;padding:70px 0;background:radial-gradient(900px 520px at 50% -10%, rgba(30,136,255,.22), transparent 60%),
    linear-gradient(180deg, #030815 0%, #02040c 100%);overflow:hidden}/* ---------- CARD CONTAINERS (works for Elementor Containers) ---------- */
#card-box .e-con{position:relative;border-radius:22px;padding:42px 28px;text-align:center;background:linear-gradient(180deg, rgba(255,255,255,.07), rgba(255,255,255,.02));border:1px solid rgba(255,255,255,.10);box-shadow:0 26px 70px rgba(0,0,0,.55),
    inset 0 1px 0 rgba(255,255,255,.08);backdrop-filter:blur(10px);overflow:hidden;/* entrance */
  opacity:0;transform:translateY(18px)}/* subtle glow inside */
#card-box .e-con::before{content:"";position:absolute;inset:-70%;background:radial-gradient(circle at 50% 15%, rgba(30,136,255,.35), transparent 60%);filter:blur(60px);opacity:.18;pointer-events:none}/* hover highlight */
#card-box .e-con:hover{transform:translateY(-8px);border-color:rgba(30,136,255,.45);box-shadow:0 40px 120px rgba(0,0,0,.75),
    inset 0 1px 0 rgba(255,255,255,.10)}/* Typography like screenshot */
#card-box .elementor-heading-title{color:rgba(255,255,255,.92) !important;font-weight:700 !important;font-size:20px !important;margin-bottom:16px !important}#card-box p{color:rgba(255,255,255,.70) !important;font-size:14px !important;line-height:1.8 !important;margin:0 auto;max-width:320px}/* ---------- GRID GAPS ---------- */
#card-box .e-con-inner,
#card-box .elementor-grid{gap:26px !important}/* =========================================
   CONNECTING LINES BETWEEN CARDS
   (drawn on the grid wrapper)
========================================= */

/* Put lines behind cards */
#card-box .e-con-inner{position:relative;z-index:1}/* Horizontal line across row 1 + row 2 */
#card-box .e-con-inner::before{content:"";position:absolute;left:6%;right:6%;top:25%;height:2px;background:linear-gradient(
    to right,
    transparent,
    rgba(30,136,255,.35),
    rgba(255,255,255,.12),
    rgba(30,136,255,.35),
    transparent
  );opacity:.75;z-index:0}/* Second row horizontal line */
#card-box .e-con-inner::after{content:"";position:absolute;left:6%;right:6%;top:75%;height:2px;background:linear-gradient(
    to right,
    transparent,
    rgba(30,136,255,.35),
    rgba(255,255,255,.10),
    rgba(30,136,255,.35),
    transparent
  );opacity:.75;z-index:0}/* Optional: vertical connector line between row 1 & row 2 (center) */
#card-box{--cb-mid-x:50%}#card-box::after{content:"";position:absolute;left:var(--cb-mid-x);top:30%;bottom:30%;width:2px;background:linear-gradient(
    to bottom,
    transparent,
    rgba(30,136,255,.30),
    rgba(255,255,255,.10),
    rgba(30,136,255,.30),
    transparent
  );opacity:.55;z-index:0}/* Make sure cards appear above lines */
#card-box .e-con{z-index:2}/* =========================================
   ANIMATION: Fade In Up + stagger
========================================= */
@keyframes cbFadeUp{from{ opacity:0;transform:translateY(22px)}to{opacity:1;transform:translateY(0)}/* =========================================
   RESPONSIVE
   Lines off on mobile (clean)
========================================= */
@media (max-width: 1024px){/* On 2 columns, center vertical line doesn't match */
  #card-box::after{ display:none}#card-box .e-con-inner::before,
  #card-box .e-con-inner::after{left:10%;right:10%}@media (max-width: 767px){/* On 1 column, hide connecting lines */
  #card-box .e-con-inner::before,
  #card-box .e-con-inner::after,
  #card-box::after{
    display:none}#card-box .e-con{padding:34px 20px}/* Reduced motion */
@media (prefers-reduced-motion: reduce){#card-box .e-con{
    animation:none !important;opacity:1 !important;transform:none !important}/* End custom CSS */
